import json


def deep_merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        result = {}
        for key in a:
            if key in b:
                result[key] = deep_merge(a[key], b[key])
            else:
                result[key] = a[key]
        for key in b:
            if key not in a:
                result[key] = b[key]
        return result
    elif isinstance(a, list) and isinstance(b, list):
        result = list(a)
        seen = set(json.dumps(item, sort_keys=True) for item in a)
        for item in b:
            item_key = json.dumps(item, sort_keys=True)
            if item_key not in seen:
                result.append(item)
                seen.add(item_key)
        return result
    else:
        return b


def main():
    path_a = '<tmp>'
    path_b = '<tmp>'

    with open(path_a, 'r') as f:
        a = json.load(f)
    with open(path_b, 'r') as f:
        b = json.load(f)

    merged = deep_merge(a, b)
    print(json.dumps(merged, indent=2, sort_keys=True))


