import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        List<String[]> rows = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String header = br.readLine();
            String line;
            while ((line = br.readLine()) != null) {
                if (line.trim().isEmpty()) continue;
                rows.add(line.split(","));
            }
        }

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCounts = new TreeMap<>();
        String highestName = "";
        double highestSalary = -1;
        double totalBudget = 0;

        for (String[] row : rows) {
            String name = row[1].trim();
            String department = row[2].trim();
            double salary = Double.parseDouble(row[3].trim());

            deptSalaries.computeIfAbsent(department, k -> new ArrayList<>()).add(salary);
            deptCounts.merge(department, 1, Integer::sum);
            totalBudget += salary;

            if (salary > highestSalary) {
                highestSalary = salary;
                highestName = name;
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== Salary Report ===\n");
        sb.append("\n");
        sb.append("Average Salary by Department:\n");

        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            String dept = entry.getKey();
            List<Double> salaries = entry.getValue();
            double avg = 0;
            for (double s : salaries) avg += s;
            avg /= salaries.size();
            sb.append(String.format("  %s: $%,.2f\n", dept, avg));
        }

        sb.append("\n");
        sb.append(String.format("Highest Paid: %s ($%,.0f)\n", highestName, highestSalary));
        sb.append("\n");
        sb.append("Departments with >2 employees:\n");

        for (Map.Entry<String, Integer> entry : deptCounts.entrySet()) {
            if (entry.getValue() > 2) {
                sb.append(String.format("  %s (%d employees)\n", entry.getKey(), entry.getValue()));
            }
        }

        sb.append("\n");
        sb.append(String.format("Total Budget: $%,.0f\n", totalBudget));

        System.out.print(sb.toString());
    }
}

