let filePath = "<tmp>"

let content = try String(contentsOfFile: filePath, encoding: .utf8)
let lines = content.components(separatedBy: "\n").filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

let dataLines = lines.dropFirst()

var departments: [String: [Double]] = [:]
var names: [String] = []
var salaries: [Double] = []

for line in dataLines {
    let cols = line.components(separatedBy: ",")
    guard cols.count >= 6 else { continue }
    let name = cols[1].trimmingCharacters(in: .whitespaces)
    let dept = cols[2].trimmingCharacters(in: .whitespaces)
    let salary = Double(cols[3].trimmingCharacters(in: .whitespaces)) ?? 0

    departments[dept, default: []].append(salary)
    names.append(name)
    salaries.append(salary)
}

func formatCurrency(_ value: Double, decimals: Int) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.minimumFractionDigits = decimals
    formatter.maximumFractionDigits = decimals
    formatter.usesGroupingSeparator = true
    formatter.groupingSeparator = ","
    return formatter.string(from: NSNumber(value: value)) ?? ""
}

print("=== Salary Report ===")
print("")
print("Average Salary by Department:")
let sortedDepts = departments.keys.sorted()
for dept in sortedDepts {
    let deptSalaries = departments[dept]!
    let avg = deptSalaries.reduce(0, +) / Double(deptSalaries.count)
    print("  \(dept): $\(formatCurrency(avg, decimals: 2))")
}
print("")

let maxSalary = salaries.max()!
let maxIndex = salaries.firstIndex(of: maxSalary)!
print("Highest Paid: \(names[maxIndex]) ($\(formatCurrency(maxSalary, decimals: 0)))")
print("")

print("Departments with >2 employees:")
for dept in sortedDepts {
    let count = departments[dept]!.count
    if count > 2 {
        print("  \(dept) (\(count) employees)")
    }
}
print("")

let total = salaries.reduce(0, +)
print("Total Budget: $\(formatCurrency(total, decimals: 0))")

