import * as fs from 'fs';

function isPlainObject(val: any): boolean {
    return val !== null && typeof val === 'object' && !Array.isArray(val);
}

function normalizeForComparison(val: any): string {
    if (Array.isArray(val)) {
        return '[' + val.map(normalizeForComparison).join(',') + ']';
    }
    if (isPlainObject(val)) {
        const keys = Object.keys(val).sort();
        return '{' + keys.map(k => JSON.stringify(k) + ':' + normalizeForComparison(val[k])).join(',') + '}';
    }
    return JSON.stringify(val);
}

function deepMerge(a: any, b: any): any {
    if (Array.isArray(a) && Array.isArray(b)) {
        const result: any[] = [...a];
        const seen = new Set<string>(a.map(item => normalizeForComparison(item)));
        for (const item of b) {
            const key = normalizeForComparison(item);
            if (!seen.has(key)) {
                seen.add(key);
                result.push(item);
            }
        }
        return result;
    }

    if (isPlainObject(a) && isPlainObject(b)) {
        const result: any = {};
        const keys = new Set<string>([...Object.keys(a), ...Object.keys(b)]);
        for (const key of keys) {
            if (key in a && key in b) {
                result[key] = deepMerge(a[key], b[key]);
            } else if (key in a) {
                result[key] = a[key];
            } else {
                result[key] = b[key];
            }
        }
        return result;
    }

    return b;
}

function sortKeys(obj: any): any {
    if (Array.isArray(obj)) {
        return obj.map(sortKeys);
    }
    if (isPlainObject(obj)) {
        const sorted: any = {};
        const keys = Object.keys(obj).sort();
        for (const key of keys) {
            sorted[key] = sortKeys(obj[key]);
        }
        return sorted;
    }
    return obj;
}

const configA = JSON.parse(fs.readFileSync('<tmp>', 'utf-8'));
const configB = JSON.parse(fs.readFileSync('<tmp>', 'utf-8'));

const merged = deepMerge(configA, configB);
const sorted = sortKeys(merged);
process.stdout.write(JSON.stringify(sorted, null, 2) + '\n');

