let filePath = "<tmp>"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    FileHandle.standardError.write("Error reading file\n".data(using: .utf8)!)
    exit(1)
}

let lines = content.components(separatedBy: "\n").filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

var levelCounts: [String: Int] = [:]
var componentErrors: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [String: Int] = [:]

let pattern = "\\[(\\d{4}-\\d{2}-\\d{2}) (\\d{2}):(\\d{2}):(\\d{2})\\] (\\w+) \\(([^)]+)\\) - (.+)"
let regex = try! NSRegularExpression(pattern: pattern)

for line in lines {
    let range = NSRange(line.startIndex..., in: line)
    guard let match = regex.firstMatch(in: line, options: [], range: range) else { continue }

    func captured(_ group: Int) -> String {
        let r = match.range(at: group)
        return String(line[Range(r, in: line)!])
    }

    let hour = captured(2)
    let level = captured(5)
    let component = captured(6)
    let message = captured(7)

    levelCounts[level, default: 0] += 1
    hourCounts[hour, default: 0] += 1

    if level == "ERROR" {
        componentErrors[component, default: 0] += 1
        errorMessages.insert(message)
    }
}

print("=== Log Analysis ===")
print("")
print("Entries by Level:")
for level in levelCounts.keys.sorted() {
    print("  \(level): \(levelCounts[level]!)")
}
print("")

if let maxComp = componentErrors.max(by: { $0.value < $1.value }) {
    print("Component with Most Errors: \(maxComp.key) (\(maxComp.value) errors)")
} else {
    print("Component with Most Errors: N/A (0 errors)")
}

print("")
print("Unique Error Messages:")
for msg in errorMessages.sorted() {
    print("  - \(msg)")
}
print("")

if let maxHour = hourCounts.max(by: { $0.value < $1.value }) {
