import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> errorComponentCounts = new TreeMap<>();
        Set<String> errorMessages = new TreeSet<>();
        Map<String, Integer> hourCounts = new TreeMap<>();

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                line = line.trim();
                if (line.isEmpty()) continue;

                int bracketEnd = line.indexOf(']');
                if (bracketEnd == -1) continue;

                String timestamp = line.substring(1, bracketEnd);

                String rest = line.substring(bracketEnd + 2);

                int spaceAfterLevel = rest.indexOf(' ');
                if (spaceAfterLevel == -1) continue;
                String level = rest.substring(0, spaceAfterLevel);

                String afterLevel = rest.substring(spaceAfterLevel + 1);

                int parenStart = afterLevel.indexOf('(');
                int parenEnd = afterLevel.indexOf(')');
                if (parenStart == -1 || parenEnd == -1) continue;
                String component = afterLevel.substring(parenStart + 1, parenEnd);

                String afterParen = afterLevel.substring(parenEnd + 2);

                String message;
                if (afterParen.startsWith("- ")) {
                    message = afterParen.substring(2);
                } else {
                    message = afterParen;
                }

                levelCounts.merge(level, 1, Integer::sum);

                if (level.equalsIgnoreCase("ERROR")) {
                    errorComponentCounts.merge(component, 1, Integer::sum);
                    errorMessages.add(message);
                }

                String hourStr = timestamp.substring(11, 13);
                hourCounts.merge(hourStr, 1, Integer::sum);
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== Log Analysis ===\n");
        sb.append("\n");
        sb.append("Entries by Level:\n");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            sb.append("  ").append(entry.getKey()).append(": ").append(entry.getValue()).append("\n");
        }
        sb.append("\n");

        String topComponent = "";
        int topCount = 0;
        for (Map.Entry<String, Integer> entry : errorComponentCounts.entrySet()) {
            if (entry.getValue() > topCount) {
                topCount = entry.getValue();
                topComponent = entry.getKey();
            }
        }
        sb.append("Component with Most Errors: ").append(topComponent).append(" (").append(topCount).append(" errors)\n");
        sb.append("\n");

        sb.append("Unique Error Messages:\n");
        for (String msg : errorMessages) {
            sb.append("  - ").append(msg).append("\n");
        }
        sb.append("\n");

        String busiestHour = "";
        int busiestCount = 0;
        for (Map.Entry<String, Integer> entry : hourCounts.entrySet()) {
            if (entry.getValue() > busiestCount) {
                busiestCount = entry.getValue();
                busiestHour = entry.getKey();
            }
        }
        sb.append("Busiest Hour: ").append(busiestHour).append(":00 (").append(busiestCount).append(" entries)\n");

        System.out.print(sb.toString());
    }
}

