use std::collections::BTreeMap;
use std::fs;

fn format_int_with_commas(n: i64) -> String {
    let negative = n < 0;
    let abs = if negative { -n } else { n };
    let s = abs.to_string();
    let len = s.len();
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    if negative {
        result.insert(0, '-');
    }
    result
}

fn format_money_2dp(n: f64) -> String {
    let rounded = (n * 100.0).round() / 100.0;
    let int_part = rounded as i64;
    let dec_part = ((rounded - int_part as f64) * 100.0).round() as i32;
    format!("{}.{:02}", format_int_with_commas(int_part), dec_part)
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read CSV file");
    let lines: Vec<&str> = content.lines().collect();

    let header: Vec<&str> = lines[0].split(',').map(|h| h.trim()).collect();
    let name_idx = header.iter().position(|h| *h == "name").unwrap();
    let dept_idx = header.iter().position(|h| *h == "department").unwrap();
    let salary_idx = header.iter().position(|h| *h == "salary").unwrap();

    let mut dept_salaries: BTreeMap<String, Vec<f64>> = BTreeMap::new();
    let mut highest_name = String::new();
    let mut highest_salary: f64 = 0.0;
    let mut total_budget: f64 = 0.0;

    for line in lines[1..].iter() {
        if line.trim().is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').map(|f| f.trim()).collect();
        let name = fields[name_idx].to_string();
        let dept = fields[dept_idx].to_string();
        let salary: f64 = fields[salary_idx].parse().unwrap();

        dept_salaries.entry(dept).or_insert_with(Vec::new).push(salary);

        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name;
        }

        total_budget += salary;
    }

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for (dept, salaries) in &dept_salaries {
        let avg = salaries.iter().sum::<f64>() / salaries.len() as f64;
        println!("  {}: ${}", dept, format_money_2dp(avg));
    }
    println!();
    println!("Highest Paid: {} (${})", highest_name, format_int_with_commas(highest_salary as i64));
    println!();
    println!("Departments with >2 employees:");
    for (dept, salaries) in &dept_salaries {
        if salaries.len() > 2 {
            println!("  {} ({} employees)", dept, salaries.len());
        }
    }
    println!();
    println!("Total Budget: ${}", format_int_with_commas(total_budget as i64));
}

