import json
import heapq

def main():
    with open("<tmp>", "r") as f:
        data = json.load(f)

    nodes = data["nodes"]
    edges = data["edges"]

    adj = {node: [] for node in nodes}
    for edge in edges:
        adj[edge["from"]].append((edge["to"], edge["weight"]))
        adj[edge["to"]].append((edge["from"], edge["weight"]))

    dist = {node: float('inf') for node in nodes}
    dist["A"] = 0

    heap = [(0, "A")]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))

    print("=== Shortest Paths from A ===")
    print()
    for node in sorted(nodes):
        d = dist[node]
        if d == float('inf'):
            print(f"A -> {node}: unreachable")
        elif isinstance(d, float) and d == int(d):
            print(f"A -> {node}: {int(d)}")
        else:
            print(f"A -> {node}: {d}")

main()

