import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface Graph {
    nodes: string[];
    edges: Edge[];
}

function dijkstra(nodes: string[], edges: Edge[], source: string): Map<string, number> {
    const adj = new Map<string, { neighbor: string; weight: number }[]>();
    for (const node of nodes) {
        adj.set(node, []);
    }
    for (const edge of edges) {
        adj.get(edge.from)!.push({ neighbor: edge.to, weight: edge.weight });
        adj.get(edge.to)!.push({ neighbor: edge.from, weight: edge.weight });
    }

    const dist = new Map<string, number>();
    const visited = new Set<string>();

    for (const node of nodes) {
        dist.set(node, Infinity);
    }
    dist.set(source, 0);

    for (let i = 0; i < nodes.length; i++) {
        let minNode: string | null = null;
        let minDist = Infinity;
        for (const node of nodes) {
            if (!visited.has(node) && dist.get(node)! < minDist) {
                minDist = dist.get(node)!;
                minNode = node;
            }
        }

        if (minNode === null) break;

        visited.add(minNode);

        const neighbors = adj.get(minNode)!;
        for (const { neighbor, weight } of neighbors) {
            if (!visited.has(neighbor)) {
                const newDist = dist.get(minNode)! + weight;
                if (newDist < dist.get(neighbor)!) {
                    dist.set(neighbor, newDist);
                }
            }
        }
    }

    return dist;
}

function main(): void {
    const filePath = '<tmp>';
    const data = fs.readFileSync(filePath, 'utf-8');
    const graph: Graph = JSON.parse(data);

    const distances = dijkstra(graph.nodes, graph.edges, 'A');

    const sortedNodes = [...graph.nodes].sort();

    console.log('=== Shortest Paths from A ===');
    console.log('');
    for (const node of sortedNodes) {
        const d = distances.get(node)!;
        console.log(`A -> ${node}: ${d}`);
    }
}

main();

