            sb.append(line);
        }
        reader.close();
        conn.disconnect();

        String json = sb.toString();

        List<String> names = new ArrayList<>();
        List<Double> prices = new ArrayList<>();

        int idx = 0;
        while (idx < json.length()) {
            int start = json.indexOf('{', idx);
            if (start == -1) break;
            int end = json.indexOf('}', start);
            if (end == -1) break;

            String obj = json.substring(start, end + 1);
            String name = extractStringValue(obj, "name");
            double price = extractNumericValue(obj, "price");

            names.add(name);
            prices.add(price);

            idx = end + 1;
        }

        List<Integer> filtered = new ArrayList<>();
        for (int i = 0; i < names.size(); i++) {
            if (prices.get(i) > 50.00) {
                filtered.add(i);
            }
        }

        filtered.sort((a, b) -> names.get(a).compareTo(names.get(b)));

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();

        double total = 0.0;
        for (int i : filtered) {
            System.out.printf("%s: $%.2f\n", names.get(i), prices.get(i));
            total += prices.get(i);
        }

        System.out.println();
        System.out.println("Count: " + filtered.size());
        System.out.printf("Total: $%.2f\n", total);
    }

    static String extractStringValue(String obj, String key) {
        String pattern = "\"" + key + "\"";
        int kIdx = obj.indexOf(pattern);
        if (kIdx == -1) return "";
        int colonIdx = obj.indexOf(':', kIdx + pattern.length());
        int quoteStart = obj.indexOf('"', colonIdx + 1);
        int quoteEnd = obj.indexOf('"', quoteStart + 1);
        if (quoteStart == -1 || quoteEnd == -1) return "";
        return obj.substring(quoteStart + 1, quoteEnd);
    }

    static double extractNumericValue(String obj, String key) {
        String pattern = "\"" + key + "\"";
        int kIdx = obj.indexOf(pattern);
        if (kIdx == -1) return 0.0;
        int colonIdx = obj.indexOf(':', kIdx + pattern.length());
        int valStart = colonIdx + 1;
        while (valStart < obj.length() && obj.charAt(valStart) == ' ') valStart++;
        int valEnd = valStart;
        while (valEnd < obj.length() && (Character.isDigit(obj.charAt(valEnd))
                || obj.charAt(valEnd) == '.' || obj.charAt(valEnd) == '-'
                || obj.charAt(valEnd) == '+' || obj.charAt(valEnd) == 'e'
                || obj.charAt(valEnd) == 'E')) {
            valEnd++;
        }
        return Double.parseDouble(obj.substring(valStart, valEnd));
    }
}

