        int edgesBracketStart = json.indexOf('[', edgesStart);
        int edgesBracketEnd = findMatchingBracket(json, edgesBracketStart);
        String edgesStr = json.substring(edgesBracketStart + 1, edgesBracketEnd);

        List<String> edgeObjs = new ArrayList<>();
        int depth = 0, objStart = -1;
        for (int i = 0; i < edgesStr.length(); i++) {
            char c = edgesStr.charAt(i);
            if (c == '{') {
                if (depth == 0) objStart = i;
                depth++;
            } else if (c == '}') {
                depth--;
                if (depth == 0) {
                    edgeObjs.add(edgesStr.substring(objStart + 1, i));
                }
            }
        }

