        String search = "\"" + key + "\"";
        int idx = obj.indexOf(search);
        int colonIdx = obj.indexOf(':', idx);
        int quoteStart = obj.indexOf('"', colonIdx);
        int quoteEnd = obj.indexOf('"', quoteStart + 1);
        return obj.substring(quoteStart + 1, quoteEnd);
    }

    static int extractIntValue(String obj, String key) {
        String search = "\"" + key + "\"";
        int idx = obj.indexOf(search);
        int colonIdx = obj.indexOf(':', idx);
        int numStart = colonIdx + 1;
        while (numStart < obj.length() && obj.charAt(numStart) == ' ') numStart++;
        int numEnd = numStart;
        while (numEnd < obj.length() && (Character.isDigit(obj.charAt(numEnd)) || obj.charAt(numEnd) == '-')) numEnd++;
        return Integer.parseInt(obj.substring(numStart, numEnd));
    }
