                char *dup = (char *)malloc(strlen(name) + 1);
                if (dup) {
                    strcpy(dup, name);
                    products[count].name = dup;
                    products[count].price = price;
                    count++;
                }
            }
        }

        free(obj);
        p = end;
    }

    qsort(products, (size_t)count, sizeof(Product), compare_names);

    printf("=== Filtered Products (price > $50.00) ===\n");
    printf("\n");
    for (int i = 0; i < count; i++) {
        printf("%s: $%.2f\n", products[i].name, products[i].price);
    }
    printf("\n");
    printf("Count: %d\n", count);
