fn main() {
    let content = fs::read_to_string(
        "<tmp>",
    )
    .expect("Failed to read file");

    let mut level_counts: HashMap<String, usize> = HashMap::new();
    let mut error_component_counts: HashMap<String, usize> = HashMap::new();
    let mut error_messages: Vec<String> = Vec::new();
    let mut hour_counts: HashMap<u32, usize> = HashMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let bracket_end = line.find(']').expect("No closing bracket");
        let timestamp_part = &line[1..bracket_end];

        let rest = &line[bracket_end + 2..];

        let level_end = rest.find(' ').expect("No space after level");
        let level = &rest[..level_end];

        let rest2 = &rest[level_end + 1..];

        let paren_start = rest2.find('(').expect("No opening paren");
        let paren_end = rest2.find(')').expect("No closing paren");
        let component = &rest2[paren_start + 1..paren_end];

        let after_paren = &rest2[paren_end + 1..];
        let dash_pos = after_paren.find(" - ").expect("No ' - ' found");
        let message = &after_paren[dash_pos + 3..];

        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        if level == "ERROR" {
            *error_component_counts.entry(component.to_string()).or_insert(0) += 1;
            error_messages.push(message.to_string());
        }

        let hour_str = &timestamp_part[11..13];
        let hour: u32 = hour_str.parse().expect("Invalid hour");
        *hour_counts.entry(hour).or_insert(0) += 1;
    }

    println!("=== Log Analysis ===");
    println!();

    println!("Entries by Level:");
    let mut levels: Vec<&String> = level_counts.keys().collect();
    levels.sort();
    for level in &levels {
        println!("  {}: {}", level, level_counts[level]);
    }

    println!();

    let mut sorted_components: Vec<(&String, &usize)> = error_component_counts.iter().collect();
    sorted_components.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
    if let Some((comp, count)) = sorted_components.first() {
        println!("Component with Most Errors: {} ({} errors)", comp, count);
    }

    println!();

    println!("Unique Error Messages:");
    let mut unique_msgs = error_messages;
    unique_msgs.sort();
    unique_msgs.dedup();
    for msg in &unique_msgs {
        println!("  - {}", msg);
    }

    println!();

    let mut sorted_hours: Vec<(&u32, &usize)> = hour_counts.iter().collect();
    sorted_hours.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
    if let Some((hour, count)) = sorted_hours.first() {
        println!("Busiest Hour: {:02}:00 ({} entries)", hour, count);
    }
