typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} JsonType;

typedef struct JsonValue JsonValue;

typedef struct {
    char *key;
    JsonValue *value;
} JsonPair;

struct JsonValue {
    JsonType type;
    union {
        int bool_val;
        double number_val;
        char *string_val;
        struct {
            JsonValue **items;
            size_t count;
            size_t capacity;
        } array;
        struct {
            JsonPair *pairs;
            size_t count;
            size_t capacity;
        } object;
    };
};

static JsonValue *json_new_null(void) {
    JsonValue *v = (JsonValue *)calloc(1, sizeof(JsonValue));
    v->type = JSON_NULL;
    return v;
}

static JsonValue *json_new_bool(int b) {
    JsonValue *v = (JsonValue *)calloc(1, sizeof(JsonValue));
    v->type = JSON_BOOL;
    v->bool_val = b;
    return v;
}

static JsonValue *json_new_number(double d) {
    JsonValue *v = (JsonValue *)calloc(1, sizeof(JsonValue));
    v->type = JSON_NUMBER;
    v->number_val = d;
    return v;
}

static JsonValue *json_new_string(const char *s) {
    JsonValue *v = (JsonValue *)calloc(1, sizeof(JsonValue));
    v->type = JSON_STRING;
    v->string_val = strdup(s);
    return v;
}

static JsonValue *json_new_array(void) {
    JsonValue *v = (JsonValue *)calloc(1, sizeof(JsonValue));
    v->type = JSON_ARRAY;
    v->array.capacity = 8;
    v->array.items = (JsonValue **)malloc(v->array.capacity * sizeof(JsonValue *));
    return v;
}

static JsonValue *json_new_object(void) {
    JsonValue *v = (JsonValue *)calloc(1, sizeof(JsonValue));
    v->type = JSON_OBJECT;
    v->object.capacity = 8;
    v->object.pairs = (JsonPair *)malloc(v->object.capacity * sizeof(JsonPair));
    return v;
}

static void array_push(JsonValue *arr, JsonValue *item) {
    if (arr->array.count >= arr->array.capacity) {
        arr->array.capacity *= 2;
        arr->array.items = (JsonValue **)realloc(arr->array.items, arr->array.capacity * sizeof(JsonValue *));
    }
    arr->array.items[arr->array.count++] = item;
}

static void object_add(JsonValue *obj, const char *key, JsonValue *val) {
    if (obj->object.count >= obj->object.capacity) {
        obj->object.capacity *= 2;
        obj->object.pairs = (JsonPair *)realloc(obj->object.pairs, obj->object.capacity * sizeof(JsonPair));
    }
    obj->object.pairs[obj->object.count].key = strdup(key);
    obj->object.pairs[obj->object.count].value = val;
    obj->object.count++;
}

static void json_free(JsonValue *v) {
    if (!v) return;
    switch (v->type) {
        case JSON_STRING:
            free(v->string_val);
            break;
        case JSON_ARRAY:
            for (size_t i = 0; i < v->array.count; i++)
                json_free(v->array.items[i]);
            free(v->array.items);
            break;
        case JSON_OBJECT:
            for (size_t i = 0; i < v->object.count; i++) {
                free(v->object.pairs[i].key);
                json_free(v->object.pairs[i].value);
            }
            free(v->object.pairs);
            break;
        default:
            break;
    }
    free(v);
}

