static void skip_ws(Parser *p) {
    while (p->pos < p->len && (p->buf[p->pos] == ' ' || p->buf[p->pos] == '\t' ||
           p->buf[p->pos] == '\n' || p->buf[p->pos] == '\r'))
        p->pos++;
}

static char *parse_string_raw(Parser *p) {
    /* assumes p->buf[p->pos] == '"' */
    p->pos++; /* skip opening quote */
    size_t cap = 64;
    char *out = (char *)malloc(cap);
    size_t len = 0;
    while (p->pos < p->len && p->buf[p->pos] != '"') {
        if (len + 8 >= cap) {
            cap *= 2;
            out = (char *)realloc(out, cap);
        }
        char c = p->buf[p->pos];
        if (c == '\\') {
            p->pos++;
            char esc = p->buf[p->pos];
            switch (esc) {
                case '"': out[len++] = '"'; break;
                case '\\': out[len++] = '\\'; break;
                case '/': out[len++] = '/'; break;
                case 'b': out[len++] = '\b'; break;
                case 'f': out[len++] = '\f'; break;
                case 'n': out[len++] = '\n'; break;
                case 'r': out[len++] = '\r'; break;
                case 't': out[len++] = '\t'; break;
                case 'u': {
                    unsigned int code = 0;
                    for (int i = 0; i < 4; i++) {
                        p->pos++;
                        char h = p->buf[p->pos];
                        code <<= 4;
                        if (h >= '0' && h <= '9') code |= (h - '0');
                        else if (h >= 'a' && h <= 'f') code |= (h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') code |= (h - 'A' + 10);
