/* Canonical string for comparison */
static void canonical_to_buf(const JsonValue *v, char *buf, size_t *pos, size_t cap) {
    if (!buf || *pos >= cap) return;
    switch (v->type) {
        case JSON_NULL:
            snprintf(buf + *pos, cap - *pos, "null");
            *pos += 4;
            break;
        case JSON_BOOL:
            if (v->bool_val) { snprintf(buf + *pos, cap - *pos, "true"); *pos += 4; }
            else { snprintf(buf + *pos, cap - *pos, "false"); *pos += 5; }
