                    for (int j = 0; j < (indent + 1) * 2; j++) fputc(' ', f);
                    print_json(v->array.items[i], f, indent + 1);
                    if (i + 1 < v->array.count) fputc(',', f);
                    fputc('\n', f);
                }
                for (int j = 0; j < indent * 2; j++) fputc(' ', f);
                fprintf(f, "]");
