        free(key);
        skip_ws(p);
        if (p->pos < p->len && p->buf[p->pos] == ',') {
            p->pos++;
        } else {
            break;
        }
    }
    skip_ws(p);
    if (p->pos < p->len && p->buf[p->pos] == '}') p->pos++;
    return obj;
}

static JsonValue *parse_value(Parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) return json_new_null();
    char c = p->buf[p->pos];
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == '"') {
        char *s = parse_string_raw(p);
        JsonValue *v = json_new_string(s);
        free(s);
        return v;
    }
    if (c == 't') { p->pos += 4; return json_new_bool(1); }
    if (c == 'f') { p->pos += 5; return json_new_bool(0); }
    if (c == 'n') { p->pos += 4; return json_new_null(); }
    return parse_number(p);
}

static JsonValue *parse_json(const char *buf, size_t len) {
    Parser p;
    p.buf = buf;
    p.pos = 0;
    p.len = len;
    return parse_value(&p);
}

/* Canonical string for comparison */
static void canonical_to_buf(const JsonValue *v, char *buf, size_t *pos, size_t cap) {
    if (!buf || *pos >= cap) return;
    switch (v->type) {
        case JSON_NULL:
            snprintf(buf + *pos, cap - *pos, "null");
            *pos += 4;
            break;
        case JSON_BOOL:
            if (v->bool_val) { snprintf(buf + *pos, cap - *pos, "true"); *pos += 4; }
            else { snprintf(buf + *pos, cap - *pos, "false"); *pos += 5; }
            break;
        case JSON_NUMBER: {
            if (v->number_val == (long long)v->number_val && fabs(v->number_val) < 1e15) {
                snprintf(buf + *pos, cap - *pos, "%lld", (long long)v->number_val);
            } else {
                snprintf(buf + *pos, cap - *pos, "%.17g", v->number_val);
            }
            *pos += strlen(buf + *pos);
            break;
        }
        case JSON_STRING: {
            buf[(*pos)++] = '"';
            for (const char *s = v->string_val; *s; s++) {
                if (*pos + 6 >= cap) return;
                char c = *s;
                if (c == '"') { buf[(*pos)++] = '\\'; buf[(*pos)++] = '"'; }
                else if (c == '\\') { buf[(*pos)++] = '\\'; buf[(*pos)++] = '\\'; }
                else if (c == '\n') { buf[(*pos)++] = '\\'; buf[(*pos)++] = 'n'; }
                else if (c == '\r') { buf[(*pos)++] = '\\'; buf[(*pos)++] = 'r'; }
                else if (c == '\t') { buf[(*pos)++] = '\\'; buf[(*pos)++] = 't'; }
                else if (c == '\b') { buf[(*pos)++] = '\\'; buf[(*pos)++] = 'b'; }
                else if (c == '\f') { buf[(*pos)++] = '\\'; buf[(*pos)++] = 'f'; }
                else if ((unsigned char)c < 0x20) {
                    snprintf(buf + *pos, cap - *pos, "\\u%04x", (unsigned char)c);
                    *pos += 6;
                } else {
                    buf[(*pos)++] = c;
                }
            }
            buf[(*pos)++] = '"';
            break;
        }
        case JSON_ARRAY: {
            buf[(*pos)++] = '[';
            for (size_t i = 0; i < v->array.count; i++) {
                if (i > 0) buf[(*pos)++] = ',';
                canonical_to_buf(v->array.items[i], buf, pos, cap);
            }
            buf[(*pos)++] = ']';
            break;
        }
        case JSON_OBJECT: {
            buf[(*pos)++] = '{';
            /* sort a temp copy for canonical form */
            size_t n = v->object.count;
            JsonPair *sorted = (JsonPair *)malloc(n * sizeof(JsonPair));
            for (size_t i = 0; i < n; i++) sorted[i] = v->object.pairs[i];
            /* simple insertion sort for canonical */
            for (size_t i = 1; i < n; i++) {
                JsonPair tmp = sorted[i];
                size_t j = i;
                while (j > 0 && strcmp(sorted[j-1].key, tmp.key) > 0) {
                    sorted[j] = sorted[j-1];
                    j--;
                }
                sorted[j] = tmp;
            }
            for (size_t i = 0; i < n; i++) {
                if (i > 0) buf[(*pos)++] = ',';
                buf[(*pos)++] = '"';
                for (const char *s = sorted[i].key; *s; s++) {
                    if (cap - *pos < 2) { free(sorted); return; }
                    buf[(*pos)++] = *s;
                }
                buf[(*pos)++] = '"';
                buf[(*pos)++] = ':';
                canonical_to_buf(sorted[i].value, buf, pos, cap);
            }
            buf[(*pos)++] = '}';
            free(sorted);
            break;
        }
    }
}

static char *canonical_string(const JsonValue *v) {
    size_t cap = 4096;
    char *buf = (char *)malloc(cap);
    size_t pos = 0;
    canonical_to_buf(v, buf, &pos, cap);
    buf[pos] = '\0';
    return buf;
}

/* Merge */
static JsonValue *deep_merge(JsonValue *a, JsonValue *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        JsonValue *result = json_new_object();
        /* Add all from A */
        for (size_t i = 0; i < a->object.count; i++) {
            object_add(result, a->object.pairs[i].key, json_new_null());
            json_free(result->object.pairs[result->object.count - 1].value);
            result->object.pairs[result->object.count - 1].value = a->object.pairs[i].value;
            a->object.pairs[i].value = NULL;
        }
        /* Merge/override with B */
        for (size_t i = 0; i < b->object.count; i++) {
            const char *key = b->object.pairs[i].key;
            int found = 0;
            for (size_t j = 0; j < result->object.count; j++) {
                if (strcmp(result->object.pairs[j].key, key) == 0) {
                    JsonValue *merged = deep_merge(result->object.pairs[j].value, b->object.pairs[i].value);
                    json_free(result->object.pairs[j].value);
                    result->object.pairs[j].value = merged;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                object_add(result, key, b->object.pairs[i].value);
                b->object.pairs[i].value = NULL;
            }
        }
        return result;
    }
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        JsonValue *result = json_new_array();
        /* Add all from A */
        for (size_t i = 0; i < a->array.count; i++) {
            array_push(result, a->array.items[i]);
            a->array.items[i] = NULL;
        }
        /* Add new items from B (dedup) */
        for (size_t i = 0; i < b->array.count; i++) {
            char *canon = canonical_string(b->array.items[i]);
            int dup = 0;
            for (size_t j = 0; j < result->array.count; j++) {
                char *existing = canonical_string(result->array.items[j]);
                if (strcmp(canon, existing) == 0) {
                    dup = 1;
                    free(existing);
                    break;
                }
                free(existing);
            }
            free(canon);
            if (!dup) {
                array_push(result, b->array.items[i]);
                b->array.items[i] = NULL;
            }
        }
        return result;
    }
    /* Scalar conflict or type mismatch: B overrides A */
    return b;
}

/* Sort object keys */
static int cmp_pairs(const void *a, const void *b) {
    const JsonPair *pa = (const JsonPair *)a;
    const JsonPair *pb = (const JsonPair *)b;
    return strcmp(pa->key, pb->key);
}

static void sort_object_keys(JsonValue *v) {
    if (v->type == JSON_OBJECT) {
        qsort(v->object.pairs, v->object.count, sizeof(JsonPair), cmp_pairs);
        for (size_t i = 0; i < v->object.count; i++)
            sort_object_keys(v->object.pairs[i].value);
    } else if (v->type == JSON_ARRAY) {
        for (size_t i = 0; i < v->array.count; i++)
            sort_object_keys(v->array.items[i]);
    }
}

/* Pretty print */
static void print_string_escaped(const char *s, FILE *f) {
    fputc('"', f);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        if (c == '"') fputs("\\\"", f);
        else if (c == '\\') fputs("\\\\", f);
        else if (c == '\n') fputs("\\n", f);
        else if (c == '\r') fputs("\\r", f);
        else if (c == '\t') fputs("\\t", f);
        else if (c == '\b') fputs("\\b", f);
        else if (c == '\f') fputs("\\f", f);
        else if (c < 0x20) fprintf(f, "\\u%04x", c);
        else fputc(c, f);
    }
    fputc('"', f);
}

static void print_number(double d, FILE *f) {
    if (d == (long long)d && fabs(d) < 1e15) {
        fprintf(f, "%lld", (long long)d);
    } else {
        /* Try to find shortest representation */
        char buf[64];
        snprintf(buf, sizeof(buf), "%.17g", d);
        /* Check if it's actually an integer value */
        if (fabs(d - floor(d)) < 1e-10 && fabs(d) < 1e15) {
            fprintf(f, "%lld", (long long)d);
        } else {
            fprintf(f, "%s", buf);
        }
    }
}

static void print_json(const JsonValue *v, FILE *f, int indent) {
    switch (v->type) {
        case JSON_NULL:
            fprintf(f, "null");
            break;
        case JSON_BOOL:
            fprintf(f, v->bool_val ? "true" : "false");
            break;
        case JSON_NUMBER:
            print_number(v->number_val, f);
            break;
        case JSON_STRING:
            print_string_escaped(v->string_val, f);
            break;
        case JSON_ARRAY:
            if (v->array.count == 0) {
                fprintf(f, "[]");
            } else {
                fprintf(f, "[\n");
                for (size_t i = 0; i < v->array.count; i++) {
                    for (int j = 0; j < (indent + 1) * 2; j++) fputc(' ', f);
                    print_json(v->array.items[i], f, indent + 1);
                    if (i + 1 < v->array.count) fputc(',', f);
                    fputc('\n', f);
                }
                for (int j = 0; j < indent * 2; j++) fputc(' ', f);
                fprintf(f, "]");
            }
            break;
        case JSON_OBJECT:
            if (v->object.count == 0) {
                fprintf(f, "{}");
            } else {
                fprintf(f, "{\n");
                for (size_t i = 0; i < v->object.count; i++) {
                    for (int j = 0; j < (indent + 1) * 2; j++) fputc(' ', f);
                    print_string_escaped(v->object.pairs[i].key, f);
                    fprintf(f, ": ");
                    print_json(v->object.pairs[i].value, f, indent + 1);
                    if (i + 1 < v->object.count) fputc(',', f);
                    fputc('\n', f);
                }
                for (int j = 0; j < indent * 2; j++) fputc(' ', f);
                fprintf(f, "}");
            }
            break;
    }
}

static char *read_file(const char *path, size_t *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc((size_t)sz + 1);
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = '\0';
    *out_len = rd;
    fclose(f);
    return buf;
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    size_t len_a, len_b;
    char *buf_a = read_file(path_a, &len_a);
    char *buf_b = read_file(path_b, &len_b);

    JsonValue *a = parse_json(buf_a, len_a);
    JsonValue *b = parse_json(buf_b, len_b);

    free(buf_a);
    free(buf_b);

    JsonValue *merged = deep_merge(a, b);

    sort_object_keys(merged);

    print_json(merged, stdout, 0);
    fputc('\n', stdout);

    json_free(merged);

    return 0;
}
