#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_LINE 8192

typedef struct {
    char *name;
    char *department;
    double salary;
} Employee;

static int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char *const *)a, *(const char *const *)b);
}

static void format_comma_int(long long value, char *buf, size_t bufsize) {
    char tmp[64];
    snprintf(tmp, sizeof(tmp), "%lld", value);
    int len = (int)strlen(tmp);
    char rev[64];
    int rpos = 0;
    int count = 0;
    for (int i = len - 1; i >= 0; i--) {
        if (count > 0 && count % 3 == 0) {
            rev[rpos++] = ',';
        }
        rev[rpos++] = tmp[i];
        count++;
    }
    for (int i = 0; i < rpos; i++) {
        buf[i] = rev[rpos - 1 - i];
    }
    buf[rpos] = '\0';
}

int main(void) {
    const char *filepath = "<tmp>";

    FILE *f = fopen(filepath, "r");
    if (!f) {
        perror("fopen");
        return 1;
    }

    Employee *employees = NULL;
    int count = 0, capacity = 0;
    char line[MAX_LINE];

    if (!fgets(line, sizeof(line), f)) {
        fclose(f);
        printf("=== Salary Report ===\n\n");
        return 0;
    }

    while (fgets(line, sizeof(line), f)) {
        line[strcspn(line, "\r\n")] = '\0';
        if (line[0] == '\0') continue;

        if (count >= capacity) {
            capacity = capacity > 0 ? capacity * 2 : 64;
            employees = (Employee *)realloc(employees, capacity * sizeof(Employee));
            if (!employees) {
                fprintf(stderr, "realloc failed\n");
                return 1;
            }
        }

        char *saveptr = NULL;
        char *fields[6];
        int nf = 0;
        char *tok = strtok_r(line, ",", &saveptr);
        while (tok && nf < 6) {
            fields[nf++] = tok;
            tok = strtok_r(NULL, ",", &saveptr);
        }

        if (nf < 4) continue;

        employees[count].name = strdup(fields[1]);
        employees[count].department = strdup(fields[2]);
        employees[count].salary = atof(fields[3]);
        count++;
    }

    fclose(f);

    if (count == 0) {
        printf("=== Salary Report ===\n\n");
        return 0;
    }

    char **depts = (char **)malloc((size_t)count * sizeof(char *));
    int ndepts = 0;
    for (int i = 0; i < count; i++) {
        int found = 0;
        for (int j = 0; j < ndepts; j++) {
            if (strcmp(depts[j], employees[i].department) == 0) {
                found = 1;
                break;
            }
        }
        if (!found) {
            depts[ndepts++] = employees[i].department;
        }
    }

    qsort(depts, (size_t)ndepts, sizeof(char *), cmp_str);

    int highest_idx = 0;
    for (int i = 1; i < count; i++) {
        if (employees[i].salary > employees[highest_idx].salary) {
            highest_idx = i;
        }
    }

    double total_budget = 0.0;
    for (int i = 0; i < count; i++) {
        total_budget += employees[i].salary;
    }

    char buf[64];

    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");

    for (int i = 0; i < ndepts; i++) {
        double sum = 0.0;
        int n = 0;
        for (int j = 0; j < count; j++) {
            if (strcmp(employees[j].department, depts[i]) == 0) {
                sum += employees[j].salary;
                n++;
            }
        }
        double avg = sum / (double)n;
        long long intpart = (long long)avg;
        int decimals = (int)lround((avg - (double)intpart) * 100.0);
        char comma_int[64];
        format_comma_int(intpart, comma_int, sizeof(comma_int));
        printf("  %s: $%s.%02d\n", depts[i], comma_int, decimals);
    }

    printf("\n");
    printf("Highest Paid: %s ($", employees[highest_idx].name);
    format_comma_int((long long)employees[highest_idx].salary, buf, sizeof(buf));
    printf("%s)\n", buf);

    printf("\n");
    printf("Departments with >2 employees:\n");
    for (int i = 0; i < ndepts; i++) {
        int n = 0;
        for (int j = 0; j < count; j++) {
            if (strcmp(employees[j].department, depts[i]) == 0) {
                n++;
            }
        }
        if (n > 2) {
            printf("  %s (%d employees)\n", depts[i], n);
        }
    }

