import Foundation

let baseDir = "<tmp>"
let fm = FileManager.default

struct FileEntry {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var allFiles: [String: [FileEntry]] = [:]

func walkDirectory(_ path: String) {
    guard let contents = try? fm.contentsOfDirectory(atPath: path) else { return }
    for item in contents {
        let fullPath = path + "/" + item
        var statBuf = stat()
        if lstat(fullPath, &statBuf) != 0 { continue }
        let fileType = statBuf.st_mode & S_IFMT
        if fileType == S_IFLNK { continue }
        if fileType == S_IFDIR {
            walkDirectory(fullPath)
        } else if fileType == S_IFREG {
            let relativePath = fullPath.replacingOccurrences(of: baseDir + "/", with: "")
            let fileSize = Int(statBuf.st_size)
            var lineCount = 0
            let fileURL = URL(fileURLWithPath: fullPath)
            if let data = try? Data(contentsOf: fileURL) {
                if !data.isEmpty {
                    lineCount = data.filter { $0 == 10 }.count
                    if data.last != 10 {
                        lineCount += 1
                    }
                }
            }
            let ext = (item as NSString).pathExtension
            let extKey = ext.isEmpty ? "" : "." + ext
            let entry = FileEntry(relativePath: relativePath, lines: lineCount, chars: fileSize)
            if allFiles[extKey] == nil { allFiles[extKey] = [] }
            allFiles[extKey]!.append(entry)
        }
    }
}

walkDirectory(baseDir)

print("=== File Tree Analysis ===")
print("")

var totalFiles = 0
var totalLines = 0
var totalChars = 0

let sortedExtensions = allFiles.keys.sorted()

for ext in sortedExtensions {
    let files = allFiles[ext]!.sorted { $0.relativePath < $1.relativePath }
    let extFileCount = files.count
    let extLines = files.reduce(0) { $0 + $1.lines }
    let extChars = files.reduce(0) { $0 + $1.chars }
    print("Extension: \(ext)")
    print("  Files: \(extFileCount)")
    print("  Total Lines: \(extLines)")
    print("  Total Characters: \(extChars)")
    for file in files {
        print("    \(file.relativePath): \(file.lines) lines, \(file.chars) chars")
    }
    totalFiles += extFileCount
    totalLines += extLines
    totalChars += extChars
}

print("")
print("Total: \(totalFiles) files, \(totalLines) lines, \(totalChars) characters")

