import * as fs from 'fs';
import * as path from 'path';

const rootDir = '<tmp>';

interface FileEntry {
  relativePath: string;
  lines: number;
  chars: number;
}

function countLines(filePath: string): number {
  const size = fs.statSync(filePath).size;
  if (size === 0) return 0;
  const buffer = fs.readFileSync(filePath);
  let newlines = 0;
  for (let i = 0; i < buffer.length; i++) {
    if (buffer[i] === 0x0a) newlines++;
  }
  if (buffer[buffer.length - 1] !== 0x0a) {
    newlines++;
  }
  return newlines;
}

function walkDir(dir: string, rootDir: string, visited: Set<string>): Map<string, FileEntry[]> {
  const result: Map<string, FileEntry[]> = new Map();

  let realDir: string;
  try {
    realDir = fs.realpathSync(dir);
  } catch {
    return result;
  }

  if (visited.has(realDir)) return result;
  visited.add(realDir);

  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return result;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isSymbolicLink()) continue;

    if (entry.isDirectory()) {
      const subResult = walkDir(fullPath, rootDir, visited);
      for (const [ext, files] of subResult) {
        if (!result.has(ext)) result.set(ext, []);
        result.get(ext)!.push(...files);
      }
    } else if (entry.isFile()) {
      const relativePath = path.relative(rootDir, fullPath).split(path.sep).join('/');
      const lines = countLines(fullPath);
      const chars = fs.statSync(fullPath).size;
      const ext = path.extname(entry.name);

      if (!result.has(ext)) result.set(ext, []);
      result.get(ext)!.push({ relativePath, lines, chars });
    }
  }

  return result;
}

const visited = new Set<string>();
const groups = walkDir(rootDir, rootDir, visited);

const sortedExts = Array.from(groups.keys()).sort((a, b) => {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
});

let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

const output: string[] = [];
output.push('=== File Tree Analysis ===');
output.push('');

for (const ext of sortedExts) {
  const files = groups.get(ext)!.sort((a, b) => {
    if (a.relativePath < b.relativePath) return -1;
    if (a.relativePath > b.relativePath) return 1;
    return 0;
  });
  const extLines = files.reduce((sum, f) => sum + f.lines, 0);
  const extChars = files.reduce((sum, f) => sum + f.chars, 0);

  output.push(`Extension: ${ext}`);
  output.push(`  Files: ${files.length}`);
  output.push(`  Total Lines: ${extLines}`);
  output.push(`  Total Characters: ${extChars}`);

  for (const file of files) {
    output.push(`    ${file.relativePath}: ${file.lines} lines, ${file.chars} chars`);
  }

  totalFiles += files.length;
  totalLines += extLines;
  totalChars += extChars;
}

output.push('');
output.push(`Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters`);

