static void json_escape(const char *s, char *out, size_t out_size) {
    size_t i = 0;
    for (size_t j = 0; s[j] && i < out_size - 1; j++) {
        unsigned char c = (unsigned char)s[j];
        switch (c) {
            case '"':  out[i++] = '\\'; out[i++] = '"';  break;
            case '\\': out[i++] = '\\'; out[i++] = '\\'; break;
            case '\b': out[i++] = '\\'; out[i++] = 'b';  break;
            case '\f': out[i++] = '\\'; out[i++] = 'f';  break;
            case '\n': out[i++] = '\\'; out[i++] = 'n';  break;
            case '\r': out[i++] = '\\'; out[i++] = 'r';  break;
            case '\t': out[i++] = '\\'; out[i++] = 't';  break;
            default:
