            case '\t': out[i++] = '\\'; out[i++] = 't';  break;
            default:
                if (c < 0x20) {
                    int w = snprintf(out + i, out_size - i, "\\u%04x", c);
                    if (w > 0) i += (size_t)w;
                } else {
                    out[i++] = (char)c;
                }
                break;
        }
    }
    out[i] = '\0';
}

static int run_command(const char *cmd, char *buf, size_t buf_size) {
    FILE *fp = popen(cmd, "r");
    if (!fp) return -1;
    size_t total = 0;
    size_t n;
    while (total < buf_size - 1 &&
           (n = fread(buf + total, 1, buf_size - 1 - total, fp)) > 0) {
        total += n;
    }
    buf[total] = '\0';
    int status = pclose(fp);
    return status;
}

