    char *esc_hostname = malloc(esc_size);
    char *esc_os       = malloc(esc_size);
    char *esc_arch     = malloc(esc_size);
    char *esc_username = malloc(esc_size);

    if (!hostname || !os || !arch || !username ||
        !esc_hostname || !esc_os || !esc_arch || !esc_username) {
        fprintf(stderr, "malloc failed\n");
        return 1;
    }

    run_command("hostname", hostname, buf_size);
    run_command("uname -s", os, buf_size);
    run_command("uname -m", arch, buf_size);
    run_command("whoami", username, buf_size);

