use std::io::{Read, Write};
use std::net::TcpStream;

enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(input: &str) -> Self {
        Parser { chars: input.chars().collect(), pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).copied();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse_value(&mut self) -> JsonValue {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => JsonValue::String(self.parse_string()),
            Some('t') => { self.pos += 4; JsonValue::Bool(true) }
            Some('f') => { self.pos += 5; JsonValue::Bool(false) }
            Some('n') => { self.pos += 4; JsonValue::Null }
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> JsonValue {
        self.next();
        let mut obj = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return JsonValue::Object(obj);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.next();
            let value = self.parse_value();
            obj.push((key, value));
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => panic!("Expected , or } in object"),
            }
        }
        JsonValue::Object(obj)
    }

    fn parse_array(&mut self) -> JsonValue {
        self.next();
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return JsonValue::Array(arr);
        }
        loop {
            let value = self.parse_value();
            arr.push(value);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => panic!("Expected , or ] in array"),
            }
        }
        JsonValue::Array(arr)
    }

    fn parse_string(&mut self) -> String {
        self.next();
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => {
                    match self.next() {
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('b') => s.push('\x08'),
                        Some('f') => s.push('\x0C'),
                        Some('u') => {
                            let mut hex = String::new();
                            for _ in 0..4 {
                                hex.push(self.next().unwrap());
                            }
                            let code = u32::from_str_radix(&hex, 16).unwrap();
                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        _ => panic!("Invalid escape sequence"),
                    }
                }
                Some(c) => s.push(c),
                None => panic!("Unterminated string"),
            }
        }
        s
    }

    fn parse_number(&mut self) -> JsonValue {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' || c.is_ascii_digit() {
                self.pos += 1;
            } else {
                break;
            }
        }
        let num_str: String = self.chars[start..self.pos].iter().collect();
        let num: f64 = num_str.parse().unwrap();
        JsonValue::Number(num)
    }
}

fn get_field<'a>(obj: &'a JsonValue, key: &str) -> Option<&'a JsonValue> {
    if let JsonValue::Object(pairs) = obj {
        for (k, v) in pairs {
            if k == key {
                return Some(v);
            }
        }
    }
    None
}

