public class Main {
    public static void main(String[] args) {
        int[][] A = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
        int[][] B = {{9, 8, 7}, {6, 5, 4}, {3, 2, 1}};

        int n = 3;
        int[][] C = new int[n][n];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int sum = 0;
                for (int k = 0; k < n; k++) {
                    sum += A[i][k] * B[k][j];
                }
                C[i][j] = sum;
            }
        }

        int det = determinant(C);

        System.out.println("=== Matrix Operations ===");
        System.out.println();
        System.out.println("Matrix A:");
        printMatrix(A);
        System.out.println();
        System.out.println("Matrix B:");
        printMatrix(B);
        System.out.println();
        System.out.println("A x B =");
        printMatrix(C);
        System.out.println();
        System.out.println("Determinant: " + det);
    }

    static void printMatrix(int[][] m) {
        for (int[] row : m) {
            StringBuilder sb = new StringBuilder("  ");
            for (int i = 0; i < row.length; i++) {
                if (i > 0) sb.append(" ");
                sb.append(String.format("%4d", row[i]));
            }
            System.out.println(sb.toString());
        }
    }

    static int determinant(int[][] m) {
        int n = m.length;
        if (n == 1) return m[0][0];
        if (n == 2) return m[0][0] * m[1][1] - m[0][1] * m[1][0];

        int det = 0;
        for (int j = 0; j < n; j++) {
            int[][] minor = new int[n - 1][n - 1];
            for (int i = 1; i < n; i++) {
                int col = 0;
                for (int k = 0; k < n; k++) {
                    if (k == j) continue;
                    minor[i - 1][col] = m[i][k];
                    col++;
                }
            }
            int sign = (j % 2 == 0) ? 1 : -1;
            det += sign * m[0][j] * determinant(minor);
        }
        return det;
    }
}

