import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Path root = Path.of("<tmp>");

        Map<String, List<FileEntry>> groups = new TreeMap<>();

        Files.walkFileTree(root, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                if (Files.isSymbolicLink(file)) {
                    return FileVisitResult.CONTINUE;
                }
                Path rel = root.relativize(file);
                String relStr = rel.toString().replace('\\', '/');

                String fileName = file.getFileName().toString();
                String ext;
                int lastDot = fileName.lastIndexOf('.');
                if (lastDot > 0) {
                    ext = fileName.substring(lastDot);
                } else {
                    ext = "(no extension)";
                }

                int lines = countLines(file);
                long chars = Files.size(file);

                groups.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileEntry(relStr, lines, chars));
                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult visitFileFailed(Path file, IOException exc) {
                return FileVisitResult.CONTINUE;
            }
        });

        for (List<FileEntry> list : groups.values()) {
            list.sort(Comparator.comparing(e -> e.path));
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== File Tree Analysis ===\n");
        sb.append("\n");

        int totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<FileEntry>> entry : groups.entrySet()) {
            String ext = entry.getKey();
            List<FileEntry> files = entry.getValue();

            long extLines = 0;
            long extChars = 0;
            for (FileEntry fe : files) {
                extLines += fe.lines;
                extChars += fe.chars;
            }

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(files.size()).append("\n");
            sb.append("  Total Lines: ").append(extLines).append("\n");
            sb.append("  Total Characters: ").append(extChars).append("\n");

            for (FileEntry fe : files) {
                sb.append("    ").append(fe.path).append(": ").append(fe.lines).append(" lines, ").append(fe.chars).append(" chars\n");
            }

            totalFiles += files.size();
            totalLines += extLines;
            totalChars += extChars;
        }

        sb.append("\n");
        sb.append("Total: ").append(totalFiles).append(" files, ").append(totalLines).append(" lines, ").append(totalChars).append(" characters\n");

        System.out.print(sb.toString());
    }

    static int countLines(Path file) throws IOException {
        byte[] bytes = Files.readAllBytes(file);
        if (bytes.length == 0) return 0;
        int newlines = 0;
        for (byte b : bytes) {
            if (b == '\n') newlines++;
        }
        if (bytes[bytes.length - 1] == '\n') {
            return newlines;
        } else {
            return newlines + 1;
        }
    }

    static class FileEntry {
        String path;
        int lines;
        long chars;

        FileEntry(String path, int lines, long chars) {
            this.path = path;
            this.lines = lines;
            this.chars = chars;
        }
    }
}

