function multiply(A: number[][], B: number[][]): number[][] {
    const n = A.length;
    const m = B.length;
    const p = B[0].length;
    const C: number[][] = Array.from({ length: n }, () => Array(p).fill(0));
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < p; j++) {
            for (let k = 0; k < m; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }
    return C;
}

function determinant(M: number[][]): number {
    const n = M.length;
    if (n === 1) return M[0][0];
    if (n === 2) return M[0][0] * M[1][1] - M[0][1] * M[1][0];
