use std::collections::BTreeMap;
use std::fs;
use std::io::Read;
use std::path::Path;

fn main() {
    let root = Path::new("<tmp>");

    let mut files: Vec<(String, u64, u64)> = Vec::new();
    walk(root, root, &mut files);

    let mut groups: BTreeMap<String, Vec<(String, u64, u64)>> = BTreeMap::new();
    for (rel_path, lines, chars) in &files {
        let p = Path::new(rel_path);
        let ext = p.extension()
            .map(|e| format!(".{}", e))
            .unwrap_or_else(|| ".".to_string());
        groups.entry(ext).or_default().push((rel_path.clone(), *lines, *chars));
    }

    for group in groups.values_mut() {
        group.sort_by(|a, b| a.0.cmp(&b.0));
    }

    println!("=== File Tree Analysis ===");
    println!();

    for (ext, group) in &groups {
        println!("Extension: {}", ext);
        println!("  Files: {}", group.len());
        let total_lines: u64 = group.iter().map(|f| f.1).sum();
        let total_chars: u64 = group.iter().map(|f| f.2).sum();
        println!("  Total Lines: {}", total_lines);
        println!("  Total Characters: {}", total_chars);
        for (rel_path, lines, chars) in group {
            println!("    {}: {} lines, {} chars", rel_path, lines, chars);
        }
    }

    println!();

    let total_files = files.len();
    let total_lines: u64 = files.iter().map(|f| f.1).sum();
    let total_chars: u64 = files.iter().map(|f| f.2).sum();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

fn walk(root: &Path, current: &Path, files: &mut Vec<(String, u64, u64)>) {
    let entries = match fs::read_dir(current) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };

        let path = entry.path();

        let metadata = match fs::symlink_metadata(&path) {
            Ok(m) => m,
            Err(_) => continue,
        };

        if metadata.file_type().is_symlink() {
            continue;
        }

        if metadata.is_dir() {
            walk(root, &path, files);
        } else if metadata.is_file() {
            let mut contents = Vec::new();
            if let Ok(mut f) = fs::File::open(&path) {
                if f.read_to_end(&mut contents).is_ok() {
                    let chars = contents.len() as u64;
                    let lines = count_lines(&contents);
                    let rel_path = path.strip_prefix(root)
                        .unwrap()
                        .to_string_lossy()
                        .replace('\\', "/");
                    files.push((rel_path, lines, chars));
                }
            }
        }
    }
}

fn count_lines(data: &[u8]) -> u64 {
    if data.is_empty() {
        return 0;
    }
    let mut lines = data.iter().filter(|&&b| b == b'\n').count() as u64;
    if !data.ends_with(&[b'\n']) {
        lines += 1;
    }
    lines
}

