#define N 3

int det3(int m[3][3]) {
    return m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])
         - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])
         + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]);
}

void print_matrix(const int m[N][N]) {
    for (int i = 0; i < N; i++) {
        printf("  ");
        for (int j = 0; j < N; j++) {
            if (j > 0) printf(" ");
            printf("%4d", m[i][j]);
        }
        printf("\n");
    }
}

int main(void) {
    int A[N][N] = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
    int B[N][N] = {{9, 8, 7}, {6, 5, 4}, {3, 2, 1}};
    int C[N][N] = {{0}};

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            C[i][j] = 0;
            for (int k = 0; k < N; k++) {
                C[i][j] += A[i][k] * B[k][j];
            }
        }
    }

    int det = det3(C);

    printf("=== Matrix Operations ===\n");
    printf("\n");
    printf("Matrix A:\n");
    print_matrix(A);
    printf("\n");
    printf("Matrix B:\n");
    print_matrix(B);
    printf("\n");
    printf("A x B =\n");
    print_matrix(C);
    printf("\n");
    printf("Determinant: %d\n", det);

    return 0;
}

