#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <sys/types.h>

#define BASE "<tmp>"

typedef struct {
    char *relpath;
    char *ext;
    long lines;
    long chars;
} FileInfo;

static int compare_files(const void *a, const void *b) {
    const FileInfo *fa = (const FileInfo *)a;
    const FileInfo *fb = (const FileInfo *)b;
    return strcmp(fa->relpath, fb->relpath);
}

static int compare_exts(const void *a, const void *b) {
    const char *ea = *(const char **)a;
    const char *eb = *(const char **)b;
    return strcmp(ea, eb);
}

static char *get_extension(const char *relpath) {
    const char *slash = strrchr(relpath, '/');
    const char *fname = slash ? slash + 1 : relpath;
    const char *dot = strrchr(fname, '.');
    if (dot && dot != fname) {
        return strdup(dot);
    }
    return strdup("");
}

static void process_file(const char *fullpath, const char *relpath, FileInfo **files, int *nfiles, int *cap) {
    FILE *f = fopen(fullpath, "rb");
    if (!f) return;

    long chars = 0;
    long lines = 0;
    int c;
    int last_char = -1;
    while ((c = fgetc(f)) != EOF) {
        chars++;
        if (c == '\n') lines++;
        last_char = c;
    }
    fclose(f);

    if (chars > 0 && last_char != '\n') {
        lines++;
    }

    if (*nfiles >= *cap) {
        *cap = *cap ? *cap * 2 : 64;
        *files = realloc(*files, (size_t)*cap * sizeof(FileInfo));
        if (!*files) {
            fprintf(stderr, "malloc failed\n");
            exit(1);
        }
    }

    (*files)[*nfiles].relpath = strdup(relpath);
    (*files)[*nfiles].ext = get_extension(relpath);
    (*files)[*nfiles].lines = lines;
    (*files)[*nfiles].chars = chars;
    (*nfiles)++;
}

static void walk(const char *dirpath, const char *relprefix, FileInfo **files, int *nfiles, int *cap) {
    DIR *dir = opendir(dirpath);
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        char fullpath[8192];
        snprintf(fullpath, sizeof(fullpath), "%s/%s", dirpath, entry->d_name);

        struct stat st;
        if (lstat(fullpath, &st) != 0) continue;

        char relpath[8192];
        if (relprefix[0] == '\0') {
            snprintf(relpath, sizeof(relpath), "%s", entry->d_name);
        } else {
            snprintf(relpath, sizeof(relpath), "%s/%s", relprefix, entry->d_name);
        }

        if (S_ISDIR(st.st_mode)) {
            walk(fullpath, relpath, files, nfiles, cap);
        } else if (S_ISREG(st.st_mode)) {
            process_file(fullpath, relpath, files, nfiles, cap);
        }
    }
    closedir(dir);
}

int main(void) {
    FileInfo *files = NULL;
    int nfiles = 0, cap = 0;

    walk(BASE, "", &files, &nfiles, &cap);

    if (nfiles > 0) {
        qsort(files, (size_t)nfiles, sizeof(FileInfo), compare_files);
    }

    char **exts = NULL;
    int nexts = 0;

    for (int i = 0; i < nfiles; i++) {
        int found = 0;
        for (int j = 0; j < nexts; j++) {
            if (strcmp(exts[j], files[i].ext) == 0) {
                found = 1;
                break;
            }
        }
        if (!found) {
            if (nexts >= nfiles) {
                /* shouldn't happen but guard */
            }
            if (!exts) {
                exts = malloc((size_t)nfiles * sizeof(char *));
            }
            exts[nexts++] = files[i].ext;
        }
    }

    if (nexts > 0) {
        qsort(exts, (size_t)nexts, sizeof(char *), compare_exts);
    }

    printf("=== File Tree Analysis ===\n\n");

    long total_lines = 0;
    long total_chars = 0;

    for (int i = 0; i < nexts; i++) {
        long ext_lines = 0;
        long ext_chars = 0;
        int ext_count = 0;

        for (int j = 0; j < nfiles; j++) {
            if (strcmp(files[j].ext, exts[i]) == 0) {
                ext_count++;
                ext_lines += files[j].lines;
                ext_chars += files[j].chars;
            }
        }

        printf("Extension: %s\n", exts[i]);
        printf("  Files: %d\n", ext_count);
        printf("  Total Lines: %ld\n", ext_lines);
        printf("  Total Characters: %ld\n", ext_chars);

        for (int j = 0; j < nfiles; j++) {
            if (strcmp(files[j].ext, exts[i]) == 0) {
                printf("    %s: %ld lines, %ld chars\n", files[j].relpath, files[j].lines, files[j].chars);
            }
        }

        total_lines += ext_lines;
        total_chars += ext_chars;
    }

    printf("\nTotal: %d files, %ld lines, %ld characters\n", nfiles, total_lines, total_chars);

    for (int i = 0; i < nfiles; i++) {
        free(files[i].relpath);
        free(files[i].ext);
    }
    free(files);
    if (exts) free(exts);

    return 0;
}

