    char **exts = NULL;
    int nexts = 0;

    for (int i = 0; i < nfiles; i++) {
        int found = 0;
        for (int j = 0; j < nexts; j++) {
            if (strcmp(exts[j], files[i].ext) == 0) {
                found = 1;
                break;
            }
        }
        if (!found) {
            if (nexts >= nfiles) {
