    long total_chars = 0;

    for (int i = 0; i < nexts; i++) {
        long ext_lines = 0;
        long ext_chars = 0;
        int ext_count = 0;

        for (int j = 0; j < nfiles; j++) {
            if (strcmp(files[j].ext, exts[i]) == 0) {
