                printf("    %s: %ld lines, %ld chars\n", files[j].relpath, files[j].lines, files[j].chars);
            }
        }

        total_lines += ext_lines;
        total_chars += ext_chars;
    }

    printf("\nTotal: %d files, %ld lines, %ld characters\n", nfiles, total_lines, total_chars);

    for (int i = 0; i < nfiles; i++) {
        free(files[i].relpath);
        free(files[i].ext);
    }
    free(files);
    if (exts) free(exts);

    return 0;
}
