                    Json::Number(n) => *n,
                    _ => panic!("Expected number for 'weight'"),
                };
                adj.get_mut(&from).unwrap().push((to.clone(), weight));
                adj.get_mut(&to).unwrap().push((from.clone(), weight));
            }
        }
        _ => panic!("Expected array for edges"),
    }

    // Dijkstra from "A"
    let source = "A";
    let mut dist: HashMap<String, f64> = nodes.iter().map(|n| (n.clone(), f64::INFINITY)).collect();
    let mut visited: HashMap<String, bool> = nodes.iter().map(|n| (n.clone(), false)).collect();
    dist.insert(source.to_string(), 0.0);

