    sorted_nodes.sort();

    print!("=== Shortest Paths from A ===\n");
    print!("\n");
    for n in &sorted_nodes {
        let d = dist[n];
        if d == f64::INFINITY {
            print!("A -> {}: unreachable\n", n);
        } else {
            print!("A -> {}: {}\n", n, format_dist(d));
        }
    }
